const b=$json.body??$json;
const query=String(b.query??'').trim();
const page=Math.max(1,Math.min(100,Math.floor(Number(b.page)||1)));
const limit=Math.max(1,Math.min(20,Math.floor(Number(b.limit)||20)));
const sortMap={relevance:22,cheapest:20,most_expensive:21,best_selling:7,most_viewed:4,newest:1,fastest_delivery:25,buyers_pick:27};
const sort=sortMap[String(b.sort??'relevance')];
const num=v=>v==null||v===''?null:Number(v);
const minPrice=num(b.min_price),maxPrice=num(b.max_price),categoryId=num(b.category_id);
const errors=[];
if(query.length<2)errors.push('query must contain at least 2 characters');
if(minPrice!==null&&(!Number.isFinite(minPrice)||minPrice<0))errors.push('min_price must be a non-negative Toman amount');
if(maxPrice!==null&&(!Number.isFinite(maxPrice)||maxPrice<0))errors.push('max_price must be a non-negative Toman amount');
if(minPrice!==null&&maxPrice!==null&&minPrice>maxPrice)errors.push('min_price cannot exceed max_price');
if(categoryId!==null&&(!Number.isInteger(categoryId)||categoryId<1))errors.push('category_id must be a positive integer');
if(!sort)errors.push('sort must be relevance, cheapest, most_expensive, best_selling, most_viewed, newest, fastest_delivery, or buyers_pick');
if(errors.length)return[{json:{ok:false,statusCode:400,error:errors.join('; ')}}];
return[{json:{ok:true,query,page,limit,sort,min_price:minPrice,max_price:maxPrice,category_id:categoryId,in_stock_only:b.in_stock_only!==false,source:'digikala',requested_at:new Date().toISOString()}}];

const input=$('Validate Input').first().json;
const response=$json,status=Number(response.statusCode??200);
if(status>=400)return[{json:{ok:false,statusCode:status,error:'Digikala search returned HTTP '+status+'. Stop on 403/429 and retry later; do not bypass access controls.'}}];
const body=response.body??response;
if(body.status&&Number(body.status)!==200)return[{json:{ok:false,statusCode:Number(body.status),error:'Digikala API reported an unsuccessful response.'}}];
const widgets=body.data?.widgets??[];
const listingWidgets=widgets.filter(w=>w.type==='vertical_product_listing');
if(listingWidgets.length!==1)return[{json:{ok:false,statusCode:502,error:'Expected one product listing in Digikala response; upstream response structure may have changed.'}}];
const listing=listingWidgets[0].data??{};
const productWidgets=Array.isArray(listing.widgets)?listing.widgets.filter(w=>w.type==='product'):[];
const toman=v=>{const n=Number(v);return Number.isFinite(n)&&n>0?Math.round(n/10):null};
const seen=new Set(),rows=[];
for(const w of productWidgets){
 const p=w.data??{},v=p.default_variant??{},price=v.price??{},seller=v.seller??{},brand=p.brand??{},category=p.category??{},rating=p.rating??{};
 const pid=String(p.id??'');if(!pid||seen.has(pid))continue;seen.add(pid);
 const current=toman(price.selling_price),before=toman(price.rrp_price);
 const discount=Number(price.discount_percent??price.discount??0);
 rows.push({
  product_id:pid,product_name:String(p.title_fa??p.title??'').trim(),
  price_toman:current,original_price_toman:before,
  discount_percent:Number.isFinite(discount)?discount:null,
  in_stock:String(p.status??v.status??'').toLowerCase()==='marketable'&&Object.keys(price).length>0,
  stock_left:price.marketable_stock??null,
  seller_name:seller.title??null,seller_code:seller.code??null,
  seller_rating_percent:seller.rating?.total_rate??null,seller_rating_count:seller.rating?.total_count??null,
  rating_stars:rating.rate?Math.floor(Number(rating.rate)/2+0.5)/10:null,rating_count:rating.count??null,
  image_url:(p.images?.main?.url??[]).find(u=>String(u).startsWith('https://'))??null,
  brand:brand.title_fa??brand.title??null,category:category.title_fa??category.title??null,
  variant_id:v.id??null,color:v.color?.title??null,warranty:v.warranty?.title_fa??null,
  is_incredible:Boolean(price.is_incredible),is_digiplus:Boolean(price.is_locked_for_digiplus),
  product_url:'https://www.digikala.com/product/dkp-'+pid+'/',
  captured_at:new Date().toISOString()
 });
}
const pager=listing.pager??{};
if(!rows.length)return[{json:{ok:false,statusCode:422,error:'No products were returned. Try another Persian query or page.',query:input.query,page:input.page,total:pager.total_items??0}}];
return[{json:{ok:true,query:input.query,page:input.page,count:Math.min(rows.length,input.limit),total:pager.total_items??rows.length,total_pages:pager.total_pages??null,rows:rows.slice(0,input.limit)}}];
